#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include "reference_global_flex_binding_scan.h"
#include "disk_model_metadata_cache.h"
#include "graph_exact_equal.h"
#include <chrono>
#include <iostream>
struct BindingIndexSnapshot{OwnedGlobalFlexBindingPlanCandidate plan;std::vector<std::string> names;std::map<uint16_t,std::vector<MdlFlexControllerMetadata>> records;std::vector<uint32_t> modelVisits;double milliseconds;};
static void same(const BindingIndexSnapshot&a,const BindingIndexSnapshot&b){
 if(a.names!=b.names||a.modelVisits!=b.modelVisits||a.plan.missingMetadata!=b.plan.missingMetadata||a.plan.missingController!=b.plan.missingController||a.plan.outOfRange!=b.plan.outOfRange||a.plan.bindings.size()!=b.plan.bindings.size())throw std::runtime_error("discovery ordering/count mismatch");
 for(size_t i=0;i<a.plan.bindings.size();++i){const auto&x=a.plan.bindings[i];const auto&y=b.plan.bindings[i];if(x.operatorElement!=y.operatorElement||x.sourceAttribute!=y.sourceAttribute||x.modelElement!=y.modelElement||x.destinationAttribute!=y.destinationAttribute||x.weightIndex!=y.weightIndex)throw std::runtime_error("binding mismatch");}
 for(const auto&entry:a.records){const auto&other=b.records.at(entry.first);if(entry.second.size()!=other.size())throw std::runtime_error("metadata count");for(size_t i=0;i<other.size();++i){const auto&x=entry.second[i];const auto&y=other[i];if(x.localIndex!=y.localIndex||x.name!=y.name||x.type!=y.type||x.diskGlobalIndex!=y.diskGlobalIndex||x.minBits!=y.minBits||x.maxBits!=y.maxBits)throw std::runtime_error("metadata mismatch");}}
}
int main(int argc,char**argv){try{static_assert(sizeof(void*)==8,"x64 required");if(argc!=3)throw std::runtime_error("fixture and content root required");auto graph=loadGraph(argv[1]);auto original=graph;struct View{Graph&graph;}view{graph};DiskModelMetadataCacheCandidate cache;std::map<uint32_t,uint16_t>modelHandles;std::map<uint16_t,std::vector<MdlFlexControllerMetadata>>baseline;std::vector<uint16_t>held;auto root=std::filesystem::weakly_canonical(argv[2]);
 for(uint32_t i=0;i<graph.elements.size();++i){const auto&e=graph.elements[i];if(graph.strings.at(e.type)!="DmeGameModel")continue;for(const auto&a:e.attributes)if(graph.strings.at(a.name)=="modelName"&&a.type==5&&a.values.size()==1){std::filesystem::path relative=a.values[0].text;if(relative.is_absolute())throw std::runtime_error("absolute asset");for(const auto&part:relative)if(part=="..")throw std::runtime_error("asset traversal");auto path=std::filesystem::weakly_canonical(root/relative);auto inside=path.lexically_relative(root);if(inside.empty()||*inside.begin()=="..")throw std::runtime_error("asset outside root");auto handle=cache.acquire(path);if(handle==0xffff)continue;held.push_back(handle);modelHandles.emplace(i,handle);baseline.emplace(handle,*cache.controllers(handle));}}
 auto run=[&](bool indexed,bool missing){BindingIndexSnapshot snapshot{};snapshot.records=baseline;RecoveredGlobalFlexRegistryCandidate registry;auto resolve=[&](uint32_t model)->std::vector<MdlFlexControllerMetadata>*{snapshot.modelVisits.push_back(model);if(missing)return nullptr;auto found=modelHandles.find(model);return found==modelHandles.end()?nullptr:&snapshot.records.at(found->second);};auto start=std::chrono::steady_clock::now();snapshot.plan=indexed?discoverOwnedGlobalFlexBindingsCandidate(view,registry,resolve):discoverOwnedGlobalFlexBindingsNaiveReference(view,registry,resolve);snapshot.milliseconds=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count();snapshot.names=registry.names();return snapshot;};
 same(run(false,true),run(true,true));double naive=0,indexed=0;size_t bindings=0;
 for(unsigned trial=0;trial<20;++trial){BindingIndexSnapshot a,b;if(trial&1){b=run(true,false);a=run(false,false);}else{a=run(false,false);b=run(true,false);}same(a,b);naive+=a.milliseconds;indexed+=b.milliseconds;bindings=b.plan.bindings.size();}
 if(!graphExactEqualCandidate(original,graph))throw std::runtime_error("discovery modified graph");for(auto handle:held)cache.release(handle);std::cout<<"bindings="<<bindings<<" trials=20 binding_registry_metadata_model_order_missing_graph_equivalence=passed naive_mean_ms="<<naive/20<<" indexed_mean_ms="<<indexed/20<<" discovery_speedup="<<naive/indexed<<" disk_import_execution_export_excluded=1 serial=1\n";return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
